mapper.select:
select a.*, c.MOLDING_MACHINE_CLASS_NAME, c.MOULD_METHOD moldingMethod, b.CLASSES, b.PRODUCT_TYPE_CODE, b.MOLDING_MACHINE_CODE from t_mdm_molding_machine_status a left join t_mdm_molding_machine b on a.MOLDING_MACHINE_ID = b.id and ifnull(b.is_delete, 0) = 0 left join t_mdm_molding_machine_CLS c on b.MOLDING_MACHINE_CLASS_ID = c.id and c.is_delete = 0 where ifnull(a.is_delete, 0) = 0
and a.year = #{year}
and a.month = #{month}
and a.factory_code = #{factoryCode} and a.status = #{status} and b.PRODUCT_TYPE_CODE = #{productTypeCode} ${params.dataScope} order by a.factory_code,b.product_type_code, REGEXP_REPLACE(b.MOLDING_MACHINE_CODE,'[^0-9]',''), ifnull(REGEXP_REPLACE(b.MOLDING_MACHINE_CODE,'[0-9]',''),'0') asc

